// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address owner, address logger, bool status) public {
        // Assume owner is not zero address to avoid revert on onlyOwner
        vm.assume(owner != address(0));
        // Let the caller be the contract owner (setOwner not exposed, but we can use prank)
        // We need to set the owner. The contract has a private _contractOwner; we cannot set it.
        // Instead, we can test the invariant over the public getter for the mapping after calling setApprovedLogger.
        // But we cannot call onlyOwner without being the owner. Since the contract has no public setOwner, we cannot become owner.
        // So we test a different invariant: the difference between reference and mutant is in the mapping update.
        // We can directly call setApprovedLogger via the owner? But we don't know the owner.
        // Instead, we can use a different approach: the invariant is that after setApprovedLogger, the mapping at logger equals !status for the mutant.
        // But we cannot bypass onlyOwner. However, the test framework allows us to use vm.prank to impersonate the owner if we know the owner.
        // The contract does not expose the owner. So we cannot test this directly with the given setup.
        // We need a different invariant that can be tested without knowing the owner.
        // Let's consider: the approvedLoggers mapping only changes via setApprovedLogger, which is onlyOwner.
        // The only way to get the mapping to change is to call setApprovedLogger as the owner.
        // But we don't know who the owner is. The owner is set in the constructor? The contract does not have a constructor setting _contractOwner.
        // Actually, the contract has no constructor. _contractOwner is never set. It defaults to address(0).
        // So the onlyOwner check requires msg.sender == address(0). That is the zero address.
        // So we can call setApprovedLogger as address(0) using vm.prank.
        vm.prank(address(0));
        c.setApprovedLogger(logger, status);
        // Now check the mapping
        bool actual = c.approvedLoggers(logger);
        // For the reference, actual should equal status; for the mutant, actual should equal !status.
        // We don't know which version we have, but we can assert that the mapping should equal status for a correct contract.
        // That's the property the reference satisfies. The mutant fails this.
        assertTrue(actual == status, "approvedLoggers should equal the given status");
    }
}

